param([Parameter(Mandatory=$true)][string]$RepoRoot,[Parameter(Mandatory=$true)][string]$SourceFile,[Parameter(Mandatory=$true)][string]$ExpectedSha256,[Parameter(Mandatory=$true)][string]$UploadRoot,[string]$TargetName="",[switch]$Execute)
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop"
$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path;. (Join-Path $PSScriptRoot "_lib_ld_receipts_v1.ps1");. (Join-Path $PSScriptRoot "_lib_ld_backend_state_v1.ps1");$blockers=@();$writes=$false;$status="blocked";$sourceSha="";$targetSha="";$SourceFile=LDBS-FullPath $SourceFile;$UploadRoot=LDBS-FullPath $UploadRoot
if(-not(Test-Path -LiteralPath $SourceFile -PathType Leaf)){$blockers+=,"SOURCE_FILE_MISSING"};if(-not(Test-Path -LiteralPath $UploadRoot -PathType Container)){$blockers+=,"UPLOAD_ROOT_MISSING"};if([string]::IsNullOrWhiteSpace($TargetName)){$TargetName=Split-Path -Leaf $SourceFile};if($TargetName-ne(Split-Path -Leaf $TargetName)-or$TargetName.Contains("..")){$blockers+=,"TARGET_NAME_INVALID"};$target=Join-Path $UploadRoot $TargetName;$temp=$target+".legacy-doctor-upload.partial"
if($blockers.Count-eq0){$sourceSha=LDREC-HexSha256File $SourceFile;if($sourceSha-cne$ExpectedSha256.ToLowerInvariant()){$blockers+=,"SOURCE_HASH_MISMATCH"};if((LDBS-FullPath $target).Equals($SourceFile,[StringComparison]::OrdinalIgnoreCase)){$blockers+=,"SOURCE_TARGET_SAME"};if(Test-Path -LiteralPath $target -PathType Leaf){$targetSha=LDREC-HexSha256File $target;if($targetSha-ceq$sourceSha){$status="duplicate_verified"}else{$blockers+=,"TARGET_COLLISION"}}elseif(Test-Path -LiteralPath $target){$blockers+=,"TARGET_COLLISION"};if(Test-Path -LiteralPath $temp){$blockers+=,"STALE_UPLOAD_PARTIAL"}}
if($blockers.Count-eq0-and$status-ne"duplicate_verified"){if(-not$Execute){$status="dry_run_ready"}else{try{[IO.File]::Copy($SourceFile,$temp,$false);if((LDREC-HexSha256File $temp)-cne$sourceSha){throw "UPLOAD_TEMP_HASH_MISMATCH"};[IO.File]::Move($temp,$target);$targetSha=LDREC-HexSha256File $target;if($targetSha-cne$sourceSha){throw "UPLOAD_TARGET_HASH_MISMATCH"};if((LDREC-HexSha256File $SourceFile)-cne$sourceSha){throw "SOURCE_CHANGED_DURING_UPLOAD"};$writes=$true;$status="uploaded_verified"}catch{if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue};if(Test-Path -LiteralPath $target -PathType Leaf){Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue};$blockers+=,[string]$_.Exception.Message;$status="failed"}}}
if($blockers.Count-gt0-and$status-ne"failed"){$status="blocked"};$ok=($blockers.Count-eq0);$receipt=[ordered]@{schema="ld.upload.filesystem.receipt.v1";event_type="ld.upload.filesystem.receipt.v1";ok=[bool]$ok;availability=$(if($ok){"available"}else{"blocked"});repo_root=$RepoRoot;adapter="filesystem_or_network_share";source_file=$SourceFile;source_sha256=$sourceSha;expected_sha256=$ExpectedSha256.ToLowerInvariant();upload_root=$UploadRoot;target_path=$target;target_sha256=$targetSha;execute_requested=[bool]$Execute;writes_source=$false;writes_upload=[bool]$writes;execution_status=$status;blockers=@($blockers);created_utc=[DateTime]::UtcNow.ToString("o")};$json=$receipt|ConvertTo-Json -Depth 20 -Compress;Write-Output $json;if($ok){Write-Output "LD_VERIFIED_FILE_UPLOAD_OK"}else{Write-Output "LD_VERIFIED_FILE_UPLOAD_BLOCKED"}
